    {ιA ιB : Type*}
    [Fintype ιA] [DecidableEq ιA]
    [Fintype ιB] [DecidableEq ιB]
    {strategy : ProjStrat params ιA ιB}
    {eps : Error}
    (hpass : strategy.PassesLowIndividualDegreeTest eps) :
    strategy.pointAgreementFailureProbability ≤ 3 * eps := by sorry

